  /// Plays the audio track corresponding to the provided text or cue key.
  static Future<bool> play(String text, {bool muted = false}) async {
    if (muted) return true;
    final file = _audioMap[text.trim()];
    if (file == null) return false;
    try {
      if (!_ready) {
        _ready = true;
        await _player.setAudioContext(
          AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build(),
        );
      }
      await _player.stop();
      await _player.setVolume(1.0);
      await _player.setReleaseMode(ReleaseMode.stop);

      final c = Completer<void>();
      late StreamSubscription sub;
      sub = _player.onPlayerComplete.listen((_) {
        sub.cancel();
        if (!c.isCompleted) c.complete();
      });

      await _player.play(AssetSource(file));
      await c.future.timeout(const Duration(seconds: 14), onTimeout: () => sub.cancel());
      return true;
    } catch (_) {
      return false;
    }
  }

  /// Stops current speech playback immediately.
  static void stop() {
    try {
      _player.stop();
    } catch (_) {}
  }
